from pathlib import Path
import os
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1'
import numpy as np,pandas as pd
H=Path(__file__).resolve().parent;O=H/'host';m=pd.read_csv(O/'strict_paired_analysis_cohort.tsv',sep='\t').set_index('tip_id');b=pd.read_csv(O/'strict1243_module_breadth.tsv.gz',sep='\t');cols=['cold_protein_quality','dna_repair_radiation','dormancy_resuscitation','osmotic_desiccation_salt','oxidative_redox','sulfur_chemolithotrophy','trace_gas_energy'];Z=pd.get_dummies(m.lineage_id,dtype=float).to_numpy();S=pd.get_dummies(m.dataset_id,dtype=float).to_numpy()[:,1:];Q=m[['completeness','contamination']].to_numpy();Q=(Q-Q.mean(0))/Q.std(0,ddof=1);xr=np.column_stack([Z,Q]);x=np.column_stack([xr,S]);r=xr.shape[1];cells=m.groupby(['lineage_id','dataset_id'],sort=True).indices;keys=list(cells);ix=list(cells.values());ls=sorted(m.lineage_id.unique());ss=sorted(m.dataset_id.unique());rng=np.random.default_rng(20261002);lw=rng.exponential(size=(2000,len(ls)));sw=rng.exponential(size=(2000,len(ss)));li=np.array([ls.index(k[0]) for k in keys]);si=np.array([ss.index(k[1]) for k in keys]);out=[];loo=[]
for branch in ['core65','restored74']:
 y=b[b.branch==branch].pivot(index='tip_id',columns='module',values='breadth').loc[m.index,cols].to_numpy();xx=np.array([x[i].T@x[i] for i in ix]);xy=np.array([x[i].T@y[i] for i in ix]);yy=np.array([(y[i]**2).sum(0) for i in ix]);ys=np.array([y[i].sum(0) for i in ix]);ns=np.array([len(i) for i in ix])
 for scheme,w in [('lineage_BB',lw[:,li]),('lineage_catalogue_product_sensitivity',lw[:,li]*sw[:,si])]:
  sr=[];sf=[]
  for j in range(0,2000,100):
   v=w[j:j+100];XX=np.einsum('bg,gij->bij',v,xx);XY=np.einsum('bg,gik->bik',v,xy);YY=v@yy;YS=v@ys;N=v@ns;var=YY/N[:,None]-(YS/N[:,None])**2;bf=np.linalg.solve(XX,XY);br=np.linalg.solve(XX[:,:r,:r],XY[:,:r]);sf.extend((YY-np.einsum('bik,bik->bk',bf,XY))/var);sr.extend((YY-np.einsum('bik,bik->bk',br,XY[:,:r]))/var)
  sr=np.array(sr);sf=np.array(sf)
  for label,mi in [('full',[0,1,2,3,4]),('drop_osmotic',[0,1,2,4])]:
   delta=(1-sf[:,mi].sum(1)/sr[:,mi].sum(1))-(1-sf[:,5:].sum(1)/sr[:,5:].sum(1));out.append(dict(branch=branch,scheme=scheme,panel=label,delta_median=np.median(delta),q025=np.quantile(delta,.025),q975=np.quantile(delta,.975),Pr_positive=np.mean(delta>0),scope="Conditional reweighting sensitivity with catalogue fixed effects; not a population or environmental posterior"))
  if scheme=='lineage_BB':assert np.allclose((1-sf[:,:5].sum(1)/sr[:,:5].sum(1))-(1-sf[:,5:].sum(1)/sr[:,5:].sum(1)),np.load(O/f'{branch}_strict_delta_BB.npy'),rtol=1e-6,atol=1e-9)
 for source in ss:
  eligible=m[m.dataset_id.ne(source)].groupby("lineage_id").dataset_id.nunique();keep=(m.dataset_id.ne(source)&m.lineage_id.isin(eligible[eligible>=2].index)).to_numpy();d=m[keep];Y=y[keep];zz=pd.get_dummies(d.lineage_id,dtype=float).to_numpy();sq=pd.get_dummies(d.dataset_id,dtype=float).to_numpy()[:,1:];qq=d[['completeness','contamination']].to_numpy();qq=(qq-qq.mean(0))/qq.std(0,ddof=1);a=np.column_stack([zz,qq]);c=np.column_stack([a,sq]);Y=(Y-Y.mean(0))/Y.std(0,ddof=1);er=Y-a@np.linalg.lstsq(a,Y,rcond=None)[0];ef=Y-c@np.linalg.lstsq(c,Y,rcond=None)[0];delta=(1-(ef[:,:5]**2).sum()/(er[:,:5]**2).sum())-(1-(ef[:,5:]**2).sum()/(er[:,5:]**2).sum());loo.append(dict(branch=branch,removed_catalogue=source,n=len(d),delta_point=delta,full_rank=np.linalg.matrix_rank(c),columns=c.shape[1],scope='Point sensitivity, not an independent replication or bootstrap interval'))
pd.DataFrame(out).to_csv(O/'strict_source_panel_sensitivity.tsv',sep='\t',index=False);pd.DataFrame(loo).to_csv(O/'strict_leave_one_catalogue.tsv',sep='\t',index=False);print(pd.DataFrame(out).to_string(index=False));print(pd.DataFrame(loo).groupby('branch').delta_point.agg(['min','max']))
